import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Browse & Filter Catalog (Shop)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/browse-and-filter-catalog.md","filePath":"api/workflows/shop/browse-and-filter-catalog.md"}'),s={name:"api/workflows/shop/browse-and-filter-catalog.md"};function i(d,e,n,l,c,p){return r(),a("div",null,e[0]||(e[0]=[o(`<h1 id="browse-filter-catalog-shop" tabindex="-1">Browse &amp; Filter Catalog (Shop) <a class="header-anchor" href="#browse-filter-catalog-shop" aria-label="Permalink to &quot;Browse &amp; Filter Catalog (Shop)&quot;">​</a></h1><p>The storefront browse path — list categories, build the filter UI from attributes, then list products with filters, sort, and pagination, and open a single product. All of this is <strong>public</strong>: the storefront key alone is enough, no customer login.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A valid storefront key (<a href="/api/setup.html">Setup</a>, <a href="/api/authentication.html">Authentication</a>).</li><li>Optional context via <code>X-LOCALE</code> / <code>X-CURRENCY</code> / <code>X-CHANNEL</code> headers (see <a href="/api/authentication.html#optional-context-headers">Authentication → Optional Context Headers</a>).</li></ul><p>Paging, sorting, and filter syntax are the same across every list — see the central <a href="/api/pagination.html">Pagination</a> and <a href="/api/sorting.html">Sorting</a> references.</p><h2 id="dependency-diagram" tabindex="-1">Dependency diagram <a class="header-anchor" href="#dependency-diagram" aria-label="Permalink to &quot;Dependency diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  key[Storefront key&lt;br/&gt;ask user] --&gt; cats[GET categories]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  key --&gt; tree[GET category tree&lt;br/&gt;navigation]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  key --&gt; attrs[GET attributes&lt;br/&gt;build filter UI]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  cats --&gt; list[GET products&lt;br/&gt;filter + sort + page]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  attrs --&gt; list</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  list --&gt; detail[GET single product]</span></span></code></pre></div><h2 id="ordered-call-table" tabindex="-1">Ordered call table <a class="header-anchor" href="#ordered-call-table" aria-label="Permalink to &quot;Ordered call table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Endpoint</th><th>Depends on</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td>List categories</td><td><a href="/api/rest-api/shop/categories/get-categories.html">GET categories</a> · <a href="/api/graphql-api/shop/category/">GraphQL</a></td><td>storefront key</td><td>Flat list; filter direct children with <code>?parent_id=N</code></td></tr><tr><td>2</td><td>Category tree (nav)</td><td><a href="/api/rest-api/shop/categories/get-category-tree.html">GET category tree</a> · <a href="/api/graphql-api/shop/category/">GraphQL</a></td><td>storefront key</td><td>Nested tree for menus</td></tr><tr><td>3</td><td>Filterable attributes</td><td><a href="/api/rest-api/shop/attributes/get-attributes.html">GET attributes</a> · <a href="/api/rest-api/shop/attributes/get-attribute-options.html">attribute options</a></td><td>storefront key</td><td>Build the filter sidebar (colour, size, …)</td></tr><tr><td>4</td><td>List / filter / sort products</td><td><a href="/api/rest-api/shop/products/get-products.html">GET products</a> · <a href="/api/rest-api/shop/products/search-product.html">search</a> · <a href="/api/graphql-api/shop/product/">GraphQL</a></td><td>a category or search term</td><td><code>?type</code> <code>?category_id</code> <code>?price</code> <code>?new</code> <code>?featured</code> <code>?&lt;attr&gt;</code> + <code>?sort</code> + <code>?page</code>/<code>?per_page</code></td></tr><tr><td>5</td><td>Single product</td><td><a href="/api/rest-api/shop/products/get-product.html">GET single product</a> · <a href="/api/graphql-api/shop/product/">GraphQL</a></td><td>a product id (REST) or <code>urlKey</code> (GraphQL)</td><td>Full detail — variants, images, price, sub-resources</td></tr></tbody></table><blockquote><p><strong>GraphQL equivalents:</strong> the fields are <code>categories</code>, <code>treeCategories(parentId:)</code> (children — <strong>not</strong> a <code>parentId</code> arg on <code>categories</code>), <code>attributes</code>, <code>products</code>, and <code>product</code>. Filters go into a single JSON <code>filter:</code> string and sort into <code>sortKey</code>/<code>reverse</code>.</p></blockquote><h2 id="end-to-end-sequence" tabindex="-1">End-to-end sequence <a class="header-anchor" href="#end-to-end-sequence" aria-label="Permalink to &quot;End-to-end sequence&quot;">​</a></h2><ul><li><strong>Category page:</strong> categories → products (<code>category_id</code>, sort, page) → single product.</li><li><strong>Search page:</strong> search-product (<code>query</code>, filters, sort, page) → single product.</li><li><strong>Filtered listing:</strong> attributes (build UI) → products (<code>?color=…&amp;size=…&amp;price=…</code>) → single product.</li></ul><p>The one thing that does not carry over literally between transports is category children: REST <code>?parent_id=</code>, GraphQL <code>treeCategories(parentId:)</code>. Everything else maps directly.</p><h2 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h2><p>To change catalog behavior on the server, see <a href="/api/workflows/customization/">Customization → Shop</a>.</p>`,15)]))}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
